+ * specific language governing permissions and limitations
+ * under the License.
+ */
+export type FolderNode = {
+  /** Direct child folders, keyed alphabetically by their display name. */
+  readonly children: Array<FolderNode>;
+  /** Last path segment, shown in the tree (e.g. ``etl``). */
+  readonly name: string;
+  /** Full folder path from the bundle root (e.g. ``team_a/etl``), used as the filter value. */
+  readonly path: string;
+};
+
+/**
+ * Build a nested folder tree from a flat list of folder paths.
+ *
+ * The backend only returns the directory of each Dag file (leaf folders), so intermediate
+ * folders that contain no Dag of their own — but do contain sub-folders — are synthesized
+ * here. Given ``["team_a/etl", "team_b/ml"]`` the ``team_a``/``team_b`` nodes are created even
+ * though no Dag lives directly in them.
+ *
+ * Children are sorted alphabetically at every level for a stable, predictable rendering.
+ */
+export const buildFolderTree = (folders: ReadonlyArray<string>): Array<FolderNode> => {
+  type MutableNode = { children: Map<string, MutableNode>; name: string; path: string };
+
+  const roots = new Map<string, MutableNode>();
+
+  for (const folder of folders) {
+    const segments = folder.split("/").filter((segment) => segment !== "");
+
+    let level = roots;
+    let prefix = "";
+
+    for (const segment of segments) {
+      prefix = prefix === "" ? segment : `${prefix}/${segment}`;
+
+      let node = level.get(segment);
+
+      if (node === undefined) {
+        node = { children: new Map(), name: segment, path: prefix };
+        level.set(segment, node);
+      }
+
+      level = node.children;
+    }
+  }
+
+  const toSortedNodes = (level: Map<string, MutableNode>): Array<FolderNode> =>
+    [...level.values()]
+      .sort((left, right) => left.name.localeCompare(right.name))
+      .map((node) => ({
+        children: toSortedNodes(node.children),
+        name: node.name,
+        path: node.path,
+      }));
+
+  return toSortedNodes(roots);
+};
+
+export type BundleFolders = {
+  /** The bundle these folders belong to. */
+  readonly bundleName: string;
+  /** Folder tree built from this bundle's folder paths. */
+  readonly tree: Array<FolderNode>;
+};
+
+/**
+ * Group folders by their bundle, then build a folder tree per bundle.
+ *
+ * Because ``relative_fileloc`` is relative to each bundle root, the same folder path
+ * can exist in several bundles; grouping first keeps them separate. Bundles are sorted
+ * alphabetically for stable rendering.
+ */
+export const groupFoldersByBundle = (
+  folders: ReadonlyArray<{ readonly bundle_name: string; readonly folder: string }>,
+): Array<BundleFolders> => {
+  const pathsByBundle = new Map<string, Array<string>>();
+
+  for (const { bundle_name: bundleName, folder } of folders) {
+    const paths = pathsByBundle.get(bundleName) ?? [];
+
+    paths.push(folder);
+    pathsByBundle.set(bundleName, paths);
+  }
+
+  return [...pathsByBundle.entries()]
+    .sort(([left], [right]) => left.localeCompare(right))
+    .map(([bundleName, paths]) => ({ bundleName, tree: buildFolderTree(paths) }));
+};
+
+export type FolderTreeNode = {
+  readonly bundleName: string;
+  readonly children?: Array<FolderTreeNode>;
+  /** Folder path within the bundle; undefined for a bundle node. */
+  readonly folder?: string;
+  readonly label: string;
+  /** Stable id used by the tree widget for selection and expansion. */
+  readonly value: string;
+};
+
+export const bundleNodeValue = (bundleName: string) => `bundle:${bundleName}`;
+export const folderNodeValue = (bundleName: string, folder: string) => `folder:${bundleName}:${folder}`;
+
+const toTreeNodes = (bundleName: string, nodes: ReadonlyArray<FolderNode>): Array<FolderTreeNode> =>
+  nodes.map((node) => ({
+    bundleName,
+    ...(node.children.length > 0 ? { children: toTreeNodes(bundleName, node.children) } : {}),
+    folder: node.path,
+    label: node.name,
+    value: folderNodeValue(bundleName, node.path),
+  }));
+
+/**
+ * Turn the folder payload into the node list the tree widget renders.
+ *
+ * With several bundles each bundle becomes a top-level node holding its own folder tree, so
+ * identical folder paths in different bundles stay distinct. With a single bundle the bundle
+ * level is dropped and folders are returned directly.
